const nextJest = require('next/jest')

const createJestConfig = nextJest({
  // Provide the path to your Next.js app to load next.config.js and .env files in your test environment
  dir: './',
})

// Add any custom config to be passed to Jest
const customJestConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/$1',
    '^nanoid$': '<rootDir>/node_modules/nanoid/index.cjs',
  },
  testMatch: [
    '**/__tests__/**/*.test.[jt]s?(x)',
  ],
  testPathIgnorePatterns: [
    '/node_modules/',
    '/e2e/',  // E2E tests run via Playwright, not Jest
  ],
  // Allow Jest to transform ESM packages (next-intl uses ESM exports)
  transformIgnorePatterns: [
    '/node_modules/(?!(next-intl|use-intl)/)',
  ],
  collectCoverageFrom: [
    'components/**/*.{js,jsx,ts,tsx}',
    'lib/**/*.{js,jsx,ts,tsx}',
    'app/**/*.{js,jsx,ts,tsx}',
    '!**/*.d.ts',
    '!**/node_modules/**',
    '!**/.next/**',
    '!**/out/**',
  ],
}

// createJestConfig is exported this way to ensure that next/jest can load the Next.js config which is async
// We must override transformIgnorePatterns AFTER next/jest generates its config,
// because next/jest's defaults would otherwise re-add next-intl to the ignore list.
module.exports = async () => {
  const jestConfig = await createJestConfig(customJestConfig)()
  jestConfig.transformIgnorePatterns = [
    '/node_modules/(?!(next-intl|use-intl|@formatjs|intl-messageformat)/)',
  ]
  return jestConfig
}

import { defineConfig, devices } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

// Load .env.local file if it exists (for KARAOKE_ACCESS_TOKEN)
const envLocalPath = path.join(__dirname, '.env.local');
if (fs.existsSync(envLocalPath)) {
  const envContent = fs.readFileSync(envLocalPath, 'utf-8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      if (key && value && !process.env[key]) {
        process.env[key] = value;
      }
    }
  }
}

// Generate a stable port per worktree directory to avoid cross-worktree conflicts.
// Each worktree gets a unique port in the 3100-3199 range based on a hash of __dirname.
// Override with E2E_PORT env var, e.g.: E2E_PORT=3001 npx playwright test
const DEFAULT_PORT = (() => {
  const dir = __dirname;
  let hash = 0;
  for (let i = 0; i < dir.length; i++) {
    hash = ((hash << 5) - hash + dir.charCodeAt(i)) | 0;
  }
  return 3100 + (Math.abs(hash) % 100); // 3100-3199
})();
const PORT = process.env.E2E_PORT || String(DEFAULT_PORT);
// Use 127.0.0.1 instead of localhost to avoid IPv6 resolution issues on macOS.
// localhost resolves to ::1 (IPv6) first, but Next.js dev server may not accept
// IPv6 connections, causing Playwright's webServer health check to hang.
const BASE_URL = `http://127.0.0.1:${PORT}`;

/**
 * Playwright configuration for karaoke-gen frontend E2E tests.
 *
 * DEFAULT: Runs regression tests with mocked API (CI-safe, offline).
 * Tests run against the local dev server with mocked API responses.
 *
 * Port configuration:
 *   E2E_PORT=3001 npx playwright test  # Run on custom port
 *
 * For production tests: use playwright.production.config.ts
 * For fixture recording: use playwright.record.config.ts
 */
export default defineConfig({
  testDir: './e2e/regression',

  // Run tests in parallel for faster CI
  fullyParallel: true,

  // Fail the build on CI if you accidentally left test.only in the source code
  forbidOnly: !!process.env.CI,

  // Retry on CI only
  retries: process.env.CI ? 2 : 0,

  // Single worker for now to avoid conflicts with real backend
  workers: 1,

  // Reporter to use
  reporter: [
    ['html', { open: 'never' }],
    ['list'],
  ],

  // Shared settings for all tests
  use: {
    // Base URL for the local dev server (configurable via E2E_PORT)
    baseURL: BASE_URL,

    // Collect trace on failure for debugging
    trace: 'on-first-retry',

    // Screenshot on failure
    screenshot: 'only-on-failure',

    // Video recording (set to 'on' to always record, 'on-first-retry' for failures only)
    video: 'on',

    // Increase timeout for real API calls
    actionTimeout: 30000,

    // Log network requests
    extraHTTPHeaders: {
      'x-playwright-test': 'true',
    },
  },

  // Longer timeout for tests hitting real backend
  timeout: 120000, // 2 minutes per test

  // Expect timeout for assertions
  expect: {
    timeout: 30000, // 30 seconds for expects
  },

  // Configure projects (browsers)
  // Regression tests only use Chromium for CI speed
  // Mobile tests set their own viewport sizes within tests
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],

  // Run local dev server before starting tests
  webServer: {
    command: `npm run dev -- -p ${PORT}`,
    url: BASE_URL,
    reuseExistingServer: !process.env.CI,
    timeout: 120000,
  },
});

import os
import pytest
import tempfile
import logging
from unittest.mock import MagicMock
from karaoke_gen.karaoke_gen import KaraokePrep
from karaoke_gen.style_loader import (
    DEFAULT_INTRO_STYLE,
    DEFAULT_END_STYLE,
    DEFAULT_KARAOKE_STYLE,
    DEFAULT_CDG_STYLE,
)
import inspect

@pytest.fixture
def mock_logger():
    """Return a mock logger for testing."""
    return MagicMock(spec=logging.Logger)

@pytest.fixture
def mock_ffmpeg():
    """Return a mock for os.system to avoid executing ffmpeg commands."""
    return MagicMock()

@pytest.fixture
def temp_dir():
    """Create a temporary directory for test files."""
    with tempfile.TemporaryDirectory() as temp_dir:
        yield temp_dir

@pytest.fixture
def complete_theme():
    """
    Return a complete theme with all required sections and fields.

    This is the standard fixture for testing code that requires themes.
    Use this instead of relying on DEFAULT_* constants with fallback logic.
    """
    return {
        "intro": DEFAULT_INTRO_STYLE.copy(),
        "end": DEFAULT_END_STYLE.copy(),
        "karaoke": DEFAULT_KARAOKE_STYLE.copy(),
        "cdg": DEFAULT_CDG_STYLE.copy(),
    }

@pytest.fixture
def basic_karaoke_gen(mock_logger, mock_ffmpeg, temp_dir):
    """Return a basic KaraokePrep instance for testing."""
    with MagicMock() as mock_os_system:
        # Create a KaraokePrep instance with required artist/title and a mock logger
        karaoke_gen = KaraokePrep(
            logger=mock_logger,
            artist="Test Artist",
            title="Test Title",
            output_dir=temp_dir,
        )

        # Replace the ffmpeg_base_command with a mock
        karaoke_gen.ffmpeg_base_command = "mock_ffmpeg"

        # Mock os.system to avoid executing commands
        karaoke_gen._os_system = mock_os_system

        yield karaoke_gen

def pytest_collection_modifyitems(items):
    """Mark async tests with asyncio marker."""
    for item in items:
        if inspect.iscoroutinefunction(item.obj):
            item.add_marker(pytest.mark.asyncio)

